function artMoksha(key, title) {
  return svgWrap(MOKSHA_ART[key] || MOKSHA_ART.sammend, 64, title);
}
function artGate(title) {
  return svgWrap(
    '<path d="M10 56 V26 H54 V56" fill="none" stroke="currentColor" stroke-width="3.4"/>' +
    '<path d="M22 56 V36 C22 28 42 28 42 36 V56" fill="none" stroke="currentColor" stroke-width="3.2"/>' +
    '<path d="M6 26 L32 10 L58 26" fill="none" stroke="currentColor" stroke-width="3.4"/>' +
    '<circle cx="32" cy="20" r="3" fill="currentColor"/>' +
    '<path d="M14 30 V56 M50 30 V56" stroke="currentColor" stroke-width="2" opacity=".6"/>',
    64, title);
}
/* The art shown on an attribute card, by attribute key. */
function attrArt(attr, th) {
  var title = '';
  if (attr === 'chinh')  return artEmblem(th.chinhSvg, L(th, 'chinhHi', 'chinhEn'));
  if (attr === 'varna')  return artDisc(th.varnaHex, L(th, 'varnaHi', 'varnaEn'));
  if (attr === 'moksha') return artMoksha(th.mokshaKey, L(th, 'mokshaHi', 'mokshaEn'));
  if (attr === 'aasan')  return artSilhouette(th.aasanKey, AASAN[th.aasanKey][S.lang]);
  if (attr === 'janma')  return artGate(L(th, 'janmaHi', 'janmaEn'));
  return artRosette(title);
}
/* The text label shown under the attribute art. */
function attrText(attr, th) {
  if (attr === 'chinh')  return L(th, 'chinhHi', 'chinhEn');
  if (attr === 'varna')  return L(th, 'varnaHi', 'varnaEn');
  if (attr === 'moksha') return L(th, 'mokshaHi', 'mokshaEn');
  if (attr === 'aasan')  return AASAN[th.aasanKey][S.lang];
  if (attr === 'janma')  return L(th, 'janmaHi', 'janmaEn');
  return '';
}
/* One-line teaching fact spoken on a successful match. */
function factLine(th, attr) {
  var name = L(th, 'hi', 'en');
  var parts = [name, attrText(attr, th)];
  if (attr !== 'moksha') parts.push(L(th, 'mokshaHi', 'mokshaEn'));
  return parts.join(' · ');
}


