const JS_SHELL = `/* ============================================================
   TOAST / DIALOG / PARTICLES
   ============================================================ */
var toastId = null;
function toast(msg) {
  var el = $('toast');
  el.textContent = msg;
  el.classList.add('is-on');
  if (toastId) clearTimeout(toastId);
  toastId = setTimeout(function () { el.classList.remove('is-on'); }, 3200);
}
function say(msg) { var el = $('live'); if (el) el.textContent = msg; }

var dlgYesFn = null, dlgLastFocus = null;
function askDialog(title, body, yesLabel, noLabel, onYes) {
  dlgLastFocus = document.activeElement;
  $('dlgTitle').textContent = title;
  $('dlgBody').textContent = body;
  $('dlgYes').textContent = yesLabel;
  $('dlgNo').textContent = noLabel;
  dlgYesFn = onYes;
  $('dialog').classList.remove('is-hidden');
  $('dlgNo').focus();
}
function closeDialog() {
  $('dialog').classList.add('is-hidden');
  dlgYesFn = null;
  if (dlgLastFocus && dlgLastFocus.focus) dlgLastFocus.focus();
}
$('dlgYes').addEventListener('click', function () { var f = dlgYesFn; closeDialog(); if (f) f(); });
$('dlgNo').addEventListener('click', closeDialog);
$('dialog').addEventListener('click', function (e) { if (e.target === $('dialog')) closeDialog(); });
document.addEventListener('keydown', function (e) {
  if (e.key === 'Escape' && !$('dialog').classList.contains('is-hidden')) closeDialog();
});

/** Muted marigold petals — transform + opacity only, skipped for reduced motion. */
function petals(count) {
  if (reduced()) return;
  var host = $('fx');
  var cols = ['#E8800C', '#C8860A', '#B23A3A', '#D4A574', '#E3B23C'];
  var n = count || 24;
  for (var i = 0; i < n; i++) {
    var p = document.createElement('i');
    var size = 7 + Math.random() * 8;
    p.style.left = (Math.random() * 100) + 'vw';
    p.style.width = size + 'px';
    p.style.height = (size * 1.35) + 'px';
    p.style.background = cols[i % cols.length];
    p.style.opacity = '.8';
    p.style.animationDuration = (2.6 + Math.random() * 2.2) + 's';
    p.style.animationDelay = (Math.random() * 0.7) + 's';
    host.appendChild(p);
    (function (node) { setTimeout(function () { if (node.parentNode) node.parentNode.removeChild(node); }, 5600); })(p);
  }
}

/* ============================================================
   LEADERBOARD · shared schema, one key for all six games
   ============================================================ */
function lbAll() {
  var o = parseJSON(rawGet(LB_KEY), {});
  return (o && typeof o === 'object' && !Array.isArray(o)) ? o : {};
}
function lbList() {
  var l = lbAll()[GAME_ID];
  if (!Array.isArray(l)) return [];
  var out = [];
  for (var i = 0; i < l.length; i++) {
    var e = l[i];
    if (!e || typeof e !== 'object') continue;
    out.push({
      name: sanitizeName(e.name), level: String(e.level || ''), levelKey: String(e.levelKey || ''),
      duration: Math.max(0, Math.floor(Number(e.duration) || 0)),
      score: Math.max(0, Math.floor(Number(e.score) || 0)),
      meta: (e.meta && typeof e.meta === 'object') ? e.meta : {},
      ts: Math.floor(Number(e.ts) || Date.now())
    });
  }
  out.sort(lbCmp);
  return out;
}
function lbCmp(a, b) { return LB_CMP(a, b); }
function lbSave(entry) {
  var all = lbAll();
  var list = Array.isArray(all[GAME_ID]) ? all[GAME_ID] : [];
  list.push(entry);
  list.sort(lbCmp);
  if (list.length > LB_MAX) list = list.slice(0, LB_MAX);
  all[GAME_ID] = list;
  var okSave = rawSet(LB_KEY, JSON.stringify(all));
  var rank = 0;
  for (var i = 0; i < list.length; i++) {
    if (list[i].ts === entry.ts && list[i].name === entry.name &&
        list[i].levelKey === entry.levelKey) { rank = i + 1; break; }
  }
  return { saved: okSave, rank: rank };
}
function lbClear() {
  var all = lbAll();
  if (Object.prototype.hasOwnProperty.call(all, GAME_ID)) {
    delete all[GAME_ID];
    rawSet(LB_KEY, JSON.stringify(all));
  }
}


`;

module.exports = { CSS_BASE, JS_TIRTH, JS_CORE, JS_SHELL };
